ROWS.update({'web_query156': ('Что найти в интернете?', 'What should I search for on the web?', 'Was soll ich im Internet suchen?', 'Que dois-je chercher sur Internet ?', '¿Qué busco en Internet?', 'Cosa devo cercare su Internet?', 'O que devo procurar na Internet?'), 'window156': ('Какое окно? Назови его заголовок.', 'Which window? Give its title.', 'Welches Fenster? Nenne den Titel.', 'Quelle fenêtre ? Indique son titre.', '¿Qué ventana? Indica su título.', 'Quale finestra? Indica il titolo.', 'Que janela? Indica o título.'), 'percent156': ('Какую громкость установить? Назови число от 0 до 100.', 'What volume? Give a number from 0 to 100.', 'Welche Lautstärke? Nenne eine Zahl von 0 bis 100.', 'Quel volume ? Donne un nombre entre 0 et 100.', '¿Qué volumen? Di un número entre 0 y 100.', 'Quale volume? Indica un numero da 0 a 100.', 'Que volume? Indica um número entre 0 e 100.'), 'audio_device156': ('Какое звуковое устройство использовать? Назови его точное имя.', 'Which audio device? Give its exact name.', 'Welches Audiogerät? Nenne den genauen Namen.', 'Quel périphérique audio ? Donne son nom exact.', '¿Qué dispositivo de audio? Di su nombre exacto.', 'Quale dispositivo audio? Indica il nome esatto.', 'Que dispositivo de áudio? Indica o nome exato.'), 'reminder156': ('О чём напомнить? Следующий ответ сохраню как текст.', 'What should I remind you about? I will keep the next reply as text.', 'Woran soll ich dich erinnern? Die nächste Antwort speichere ich als Text.', 'Que dois-je te rappeler ? Je garderai la prochaine réponse comme texte.', '¿Qué debo recordarte? Guardaré la siguiente respuesta como texto.', 'Cosa devo ricordarti? Salverò la prossima risposta come testo.', 'De que te devo lembrar? Vou guardar a próxima resposta como texto.'), 'channel156': ('Какой канал? Назови его имя или идентификатор.', 'Which channel? Give its name or ID.', 'Welcher Kanal? Nenne den Namen oder die ID.', 'Quel canal ? Indique son nom ou son identifiant.', '¿Qué canal? Indica su nombre o identificador.', 'Quale canale? Indica il nome o l’identificatore.', 'Que canal? Indica o nome ou identificador.'), 'server156': ('Какой сервер Discord?', 'Which Discord server?', 'Welcher Discord-Server?', 'Quel serveur Discord ?', '¿Qué servidor de Discord?', 'Quale server Discord?', 'Que servidor Discord?'), 'timer_id156': ('Какой таймер отменить? Назови идентификатор из списка таймеров.', 'Which timer should I cancel? Give its ID from the timer list.', 'Welchen Timer soll ich abbrechen? Nenne seine ID aus der Timerliste.', 'Quel minuteur annuler ? Indique son identifiant dans la liste.', '¿Qué temporizador cancelo? Indica su identificador de la lista.', 'Quale timer annullo? Indica l’identificatore dalla lista.', 'Que temporizador devo cancelar? Indica o identificador na lista.'), 'tab_index156': ('Какой номер вкладки?', 'Which tab number?', 'Welche Tabnummer?', 'Quel numéro d’onglet ?', '¿Qué número de pestaña?', 'Quale numero di scheda?', 'Qual o número do separador?'), 'folder_choose156': ('Открыто окон папок: {count}. Какое закрыть? Назови номер или точное имя:\n{choices}', 'There are {count} folder windows. Which should I close? Give its number or exact name:\n{choices}', 'Es sind {count} Ordnerfenster geöffnet. Welches soll ich schließen? Nenne Nummer oder Namen:\n{choices}', 'Il y a {count} fenêtres de dossiers. Laquelle fermer ? Donne son numéro ou son nom exact :\n{choices}', 'Hay {count} ventanas de carpetas. ¿Cuál cierro? Di el número o el nombre exacto:\n{choices}', 'Ci sono {count} finestre di cartelle. Quale chiudo? Indica il numero o il nome esatto:\n{choices}', 'Há {count} janelas de pastas. Qual devo fechar? Indica o número ou o nome exato:\n{choices}'), 'folder_none156': ('Открытых окон папок не нашёл.', 'I found no open folder windows.', 'Ich habe keine offenen Ordnerfenster gefunden.', 'Je n’ai trouvé aucune fenêtre de dossier ouverte.', 'No encontré ventanas de carpetas abiertas.', 'Non ho trovato finestre di cartelle aperte.', 'Não encontrei janelas de pastas abertas.'), 'folder_unavailable156': ('Не удалось получить список окон Проводника. Ничего не закрывал.', 'I could not inspect Explorer windows. Nothing was closed.', 'Ich konnte die Explorer-Fenster nicht prüfen. Nichts wurde geschlossen.', 'Impossible de lire les fenêtres de l’Explorateur. Rien n’a été fermé.', 'No pude consultar las ventanas del Explorador. No cerré nada.', 'Non ho potuto esaminare le finestre di Esplora file. Non ho chiuso nulla.', 'Não consegui consultar as janelas do Explorador. Não fechei nada.'), 'folder_changed156': ('Выбранное окно папки изменилось или уже закрыто. Повтори команду, чтобы я проверил открытые папки заново.', 'The chosen folder window changed or closed. Repeat the request so I can check the current windows.', 'Das gewählte Ordnerfenster wurde geändert oder geschlossen. Wiederhole den Befehl für eine neue Prüfung.', 'La fenêtre choisie a changé ou a été fermée. Répète la demande pour une nouvelle vérification.', 'La ventana elegida cambió o se cerró. Repite la solicitud para consultar las ventanas actuales.', 'La finestra scelta è cambiata o è stata chiusa. Ripeti la richiesta per una nuova verifica.', 'A janela escolhida mudou ou foi fechada. Repete o pedido para uma nova verificação.'), 'folder_closed156': ('Закрыл окно папки: {label}.', 'Closed the folder window: {label}.', 'Ordnerfenster geschlossen: {label}.', 'Fenêtre de dossier fermée : {label}.', 'Ventana de carpeta cerrada: {label}.', 'Finestra della cartella chiusa: {label}.', 'Janela da pasta fechada: {label}.'), 'folder_failed156': ('Не удалось закрыть окно папки: {label}.', 'Could not close the folder window: {label}.', 'Ordnerfenster konnte nicht geschlossen werden: {label}.', 'Impossible de fermer la fenêtre du dossier : {label}.', 'No pude cerrar la ventana de carpeta: {label}.', 'Non ho potuto chiudere la finestra della cartella: {label}.', 'Não consegui fechar a janela da pasta: {label}.'), 'folder_unverified156': ('Отправил запрос на закрытие окна «{label}», но оно пока открыто. Проверь, не ждёт ли Проводник ответа.', 'Requested closure of “{label}”, but it remains open. Check whether Explorer needs your response.', 'Schließen von „{label}“ angefordert, das Fenster ist noch offen. Prüfe, ob Explorer eine Antwort erwartet.', 'Fermeture de « {label} » demandée, mais la fenêtre reste ouverte. Vérifie si l’Explorateur attend une réponse.', 'Solicité cerrar «{label}», pero sigue abierta. Comprueba si el Explorador espera una respuesta.', 'Ho richiesto la chiusura di «{label}», ma è ancora aperta. Verifica se Esplora file attende una risposta.', 'Pedi o fecho de «{label}», mas a janela continua aberta. Verifica se o Explorador aguarda uma resposta.')})

ROWS.update({'file_path156': ('Какой файл использовать? Укажи полный путь.', 'Which file should I use? Give its full path.', 'Welche Datei soll ich verwenden? Nenne den vollständigen Pfad.', 'Quel fichier utiliser ? Indique son chemin complet.', '¿Qué archivo utilizo? Indica la ruta completa.', 'Quale file devo usare? Indica il percorso completo.', 'Que ficheiro devo usar? Indica o caminho completo.'), 'folder_path156': ('Какую папку использовать? Назови системную папку, например Downloads, или полный путь.', 'Which folder should I use? Give a known folder such as Downloads, or its full path.', 'Welchen Ordner soll ich verwenden? Nenne einen Standardordner wie Downloads oder den vollständigen Pfad.', 'Quel dossier utiliser ? Indique un dossier connu comme Downloads ou son chemin complet.', '¿Qué carpeta utilizo? Indica una carpeta conocida como Downloads o la ruta completa.', 'Quale cartella devo usare? Indica una cartella nota come Downloads o il percorso completo.', 'Que pasta devo usar? Indica uma pasta conhecida como Downloads ou o caminho completo.'), 'reminder_after156': ('Через сколько напомнить? Например, через 15 минут.', 'When should I remind you? For example, in 15 minutes.', 'Wann soll ich dich erinnern? Zum Beispiel in 15 Minuten.', 'Dans combien de temps dois-je te le rappeler ? Par exemple, dans 15 minutes.', '¿Dentro de cuánto tiempo te aviso? Por ejemplo, 15 minutos.', 'Fra quanto devo ricordartelo? Per esempio, fra 15 minuti.', 'Daqui a quanto tempo devo lembrar-te? Por exemplo, 15 minutos.')})

ROWS.update({'overlay_name156': ('Какую панель? Назови её имя.', 'Which panel? Give its name.', 'Welche Anzeige? Nenne ihren Namen.', 'Quel panneau ? Indique son nom.', '¿Qué panel? Indica su nombre.', 'Quale pannello? Indica il nome.', 'Que painel? Indica o nome.'), 'overlay_new_name156': ('Как назвать панель?', 'What should the panel be called?', 'Wie soll die Anzeige heißen?', 'Quel nouveau nom donner au panneau ?', '¿Qué nombre nuevo le doy al panel?', 'Quale nuovo nome devo dare al pannello?', 'Que novo nome devo dar ao painel?'), 'overlay_position156': ('Куда переместить панель? Назови положение, например «справа вверху», «по центру» или «слева внизу».', 'Where should I move the panel? Give a position such as “top right”, “center” or “bottom left”.', 'Wohin soll die Anzeige? Nenne eine Position, etwa „oben rechts“, „in der Mitte“ oder „unten links“.', 'Où déplacer le panneau ? Indique une position, par exemple « en haut à droite », « au centre » ou « en bas à gauche ».', '¿Dónde coloco el panel? Indica una posición como «arriba a la derecha», «en el centro» o «abajo a la izquierda».', 'Dove sposto il pannello? Indica una posizione come «in alto a destra», «al centro» o «in basso a sinistra».', 'Para onde movo o painel? Indica uma posição como «no alto à direita», «ao centro» ou «em baixo à esquerda».')})

def message(key: str, code: str, **values) -> str:
    index = LANGUAGES.index(code) if code in LANGUAGES else 1
    return ROWS[key][index].format(**values)

